"use client";

import type { ComponentType, ReactNode } from "react";
import type { BuildingKind, EraId } from "@/lib/content/schema";
import { pick, SHARED, type EraPalette } from "@/lib/three/palette";

/**
 * BUILDING MODEL REGISTRY (shared; island agents do not edit this file).
 *
 * One placeholder model per building kind (docs/VISION.md table), built from a handful of primitives so each
 * kind is recognisable from the isometric camera. Every model:
 * - faces local +Z (the road), sits on y = 0, and stays inside `plot` (width along the road, depth away);
 * - takes its colours from the era palette, so the same kind looks different on each island.
 *
 * Swapping in real models later:
 * - per island: pass `Model={MyLab}` to <Building> from your island file (your own component, e.g. a glTF);
 * - for everyone: replace the entry in BUILDING_MODELS below (foundation owner only).
 * Collision is a box (see Building.tsx), so a new model never needs new physics.
 */

export type BuildingModelProps = {
  kind: BuildingKind;
  eraId: EraId;
  palette: EraPalette;
  plot: { width: number; depth: number };
  /** Index for picking colours (building order on the island). */
  colourIndex: number;
  /** Text not written yet: models may show a small "under construction" hint. */
  comingSoon: boolean;
};

export type BuildingModel = ComponentType<BuildingModelProps>;

/* -------------------------------------------------------------- helpers */

type V3 = [number, number, number];

export function Block({
  size,
  position,
  color,
  rotation,
  shadow = true,
  emissive,
}: {
  size: V3;
  position: V3;
  color: string;
  rotation?: V3;
  shadow?: boolean;
  emissive?: boolean;
}) {
  return (
    <mesh position={position} rotation={rotation} castShadow={shadow} receiveShadow={shadow}>
      <boxGeometry args={size} />
      {/* Emissive defaults to black (no glow) */}
      <meshLambertMaterial color={color} {...(emissive ? { emissive: color, emissiveIntensity: 0.6 } : {})} />
    </mesh>
  );
}

function Cyl({
  r,
  h,
  position,
  color,
  segments = 10,
  rotation,
}: {
  r: number | [number, number];
  h: number;
  position: V3;
  color: string;
  segments?: number;
  rotation?: V3;
}) {
  const [top, bottom] = Array.isArray(r) ? r : [r, r];
  return (
    <mesh position={position} rotation={rotation} castShadow>
      <cylinderGeometry args={[top, bottom, h, segments]} />
      <meshLambertMaterial color={color} />
    </mesh>
  );
}

/** Footprint of the main volume inside the plot. */
function body(plot: BuildingModelProps["plot"], fw = 0.72, fd = 0.62) {
  return { w: plot.width * fw, d: plot.depth * fd };
}

function Door({ z, color, width = 1.4, height = 2.2 }: { z: number; color: string; width?: number; height?: number }) {
  return <Block size={[width, height, 0.12]} position={[0, height / 2, z]} color={color} shadow={false} />;
}

/** Small striped barrier shown in front of buildings whose content is still coming. */
function ComingSoonBarrier({ z, accent }: { z: number; accent: string }) {
  return (
    <group position={[2.4, 0, z]}>
      <Block size={[0.12, 0.8, 0.12]} position={[-0.7, 0.4, 0]} color={SHARED.ink} />
      <Block size={[0.12, 0.8, 0.12]} position={[0.7, 0.4, 0]} color={SHARED.ink} />
      <Block size={[1.8, 0.28, 0.1]} position={[0, 0.7, 0]} color={accent} />
    </group>
  );
}

function Shell({ children, p, front }: { children: ReactNode; p: BuildingModelProps; front: number }) {
  return (
    <group>
      {children}
      {p.comingSoon && <ComingSoonBarrier z={front + 1.6} accent={p.palette.accent} />}
    </group>
  );
}

/* --------------------------------------------------------------- models */

/** Podcast studio: box, flat roof, a big microphone on the roof, ON AIR lamp. */
export function PodcastStudio(p: BuildingModelProps) {
  const { w, d } = body(p.plot);
  const h = 4.2;
  const wall = pick(p.palette.buildings, p.colourIndex);
  const roof = pick(p.palette.roofs, p.colourIndex);
  return (
    <Shell p={p} front={d / 2}>
      <Block size={[w, h, d]} position={[0, h / 2, 0]} color={wall} />
      <Block size={[w + 0.4, 0.35, d + 0.4]} position={[0, h + 0.17, 0]} color={roof} />
      <Door z={d / 2 + 0.06} color={SHARED.ink} />
      <Block size={[1.6, 0.5, 0.1]} position={[0, h - 0.7, d / 2 + 0.06]} color={p.palette.accent} emissive />
      {/* Microphone */}
      <Cyl r={0.12} h={1.6} position={[w * 0.18, h + 1.1, 0]} color={SHARED.ink} />
      <mesh position={[w * 0.18, h + 2.3, 0]} castShadow>
        <capsuleGeometry args={[0.55, 0.9, 4, 10]} />
        <meshLambertMaterial color={p.palette.accent} />
      </mesh>
    </Shell>
  );
}

/** Interview booth: small cabin with a big window and two chairs under an awning. */
export function InterviewBooth(p: BuildingModelProps) {
  const { w, d } = body(p.plot, 0.55, 0.5);
  const h = 3.2;
  const wall = pick(p.palette.buildings, p.colourIndex + 1);
  return (
    <Shell p={p} front={d / 2 + 1.6}>
      <Block size={[w, h, d]} position={[0, h / 2, 0]} color={wall} />
      <Block size={[w * 0.7, h * 0.45, 0.1]} position={[0, h * 0.55, d / 2 + 0.06]} color={SHARED.carGlass} />
      <Block size={[w + 0.6, 0.18, 2]} position={[0, h - 0.2, d / 2 + 1]} color={p.palette.accent} />
      {[-0.9, 0.9].map((x) => (
        <group key={x} position={[x, 0, d / 2 + 1.2]}>
          <Block size={[0.7, 0.45, 0.7]} position={[0, 0.25, 0]} color={pick(p.palette.roofs, p.colourIndex)} />
          <Block size={[0.7, 0.7, 0.14]} position={[0, 0.8, -0.28]} color={pick(p.palette.roofs, p.colourIndex)} />
        </group>
      ))}
    </Shell>
  );
}

/** Archive (documents): wide, low, columns and a pediment, stacks of files. */
export function Archive(p: BuildingModelProps) {
  const { w, d } = body(p.plot, 0.8, 0.6);
  const h = 3.6;
  const wall = pick(p.palette.buildings, p.colourIndex);
  const trim = SHARED.cream;
  return (
    <Shell p={p} front={d / 2 + 1}>
      <Block size={[w, 0.4, d + 1.6]} position={[0, 0.2, 0.4]} color={trim} />
      <Block size={[w * 0.92, h, d]} position={[0, h / 2 + 0.4, -0.2]} color={wall} />
      {[-0.375, -0.125, 0.125, 0.375].map((f) => (
        <Cyl key={f} r={0.28} h={h} position={[w * f, h / 2 + 0.4, d / 2 + 0.4]} color={trim} segments={8} />
      ))}
      <mesh position={[0, h + 0.95, d / 2 + 0.2]} rotation={[0, 0, 0]} castShadow>
        <cylinderGeometry args={[0.01, w * 0.55, 1.1, 3, 1]} />
        <meshLambertMaterial color={pick(p.palette.roofs, p.colourIndex)} />
      </mesh>
      <Block size={[w * 0.95, 0.3, d + 0.8]} position={[0, h + 0.55, 0]} color={pick(p.palette.roofs, p.colourIndex)} />
      <Block size={[0.9, 0.5, 0.7]} position={[-w * 0.42, 0.65, d / 2 + 1.6]} color={SHARED.cream} />
      <Block size={[0.9, 0.5, 0.7]} position={[-w * 0.42, 1.15, d / 2 + 1.6]} color={p.palette.base} />
    </Shell>
  );
}

/** Research lab: box with an observatory dome and an antenna. */
export function ResearchLab(p: BuildingModelProps) {
  const { w, d } = body(p.plot);
  const h = 4.6;
  const wall = pick(p.palette.buildings, p.colourIndex + 2);
  return (
    <Shell p={p} front={d / 2}>
      <Block size={[w, h, d]} position={[0, h / 2, 0]} color={wall} />
      <Door z={d / 2 + 0.06} color={SHARED.ink} width={1.8} />
      {[-1, 1].map((s) => (
        <Block key={s} size={[1.6, 1, 0.1]} position={[s * w * 0.28, h * 0.62, d / 2 + 0.06]} color={SHARED.carGlass} />
      ))}
      <mesh position={[-w * 0.15, h, 0]} castShadow>
        <sphereGeometry args={[Math.min(w, d) * 0.33, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2]} />
        <meshLambertMaterial color={pick(p.palette.roofs, p.colourIndex)} />
      </mesh>
      <Cyl r={0.08} h={2.6} position={[w * 0.32, h + 1.3, -d * 0.2]} color={SHARED.ink} />
      <mesh position={[w * 0.32, h + 2.7, -d * 0.2]}>
        <sphereGeometry args={[0.25, 8, 6]} />
        <meshLambertMaterial color={p.palette.accent} emissive={p.palette.accent} emissiveIntensity={0.8} />
      </mesh>
    </Shell>
  );
}

/** Cinema (video): tall front with a marquee board and poster frames. */
export function Cinema(p: BuildingModelProps) {
  const { w, d } = body(p.plot, 0.75, 0.66);
  const h = 5.4;
  const wall = pick(p.palette.buildings, p.colourIndex + 1);
  return (
    <Shell p={p} front={d / 2 + 1.2}>
      <Block size={[w, h, d]} position={[0, h / 2, 0]} color={wall} />
      <Block size={[w * 0.9, 1.1, 1.2]} position={[0, h * 0.62, d / 2 + 0.6]} color={p.palette.accent} emissive />
      <Block size={[w * 0.8, 0.12, 2]} position={[0, h * 0.5, d / 2 + 1]} color={SHARED.ink} />
      <Door z={d / 2 + 0.06} color={SHARED.ink} width={2.4} />
      {[-1, 1].map((s) => (
        <Block
          key={s}
          size={[1.1, 1.6, 0.1]}
          position={[s * w * 0.34, 1.4, d / 2 + 0.06]}
          color={pick(p.palette.roofs, p.colourIndex + 1)}
        />
      ))}
    </Shell>
  );
}

/** Gallery (animation): saw-tooth roof and one big frame on the front. */
export function Gallery(p: BuildingModelProps) {
  const { w, d } = body(p.plot);
  const h = 3.8;
  const wall = pick(p.palette.buildings, p.colourIndex + 3);
  const roof = pick(p.palette.roofs, p.colourIndex);
  return (
    <Shell p={p} front={d / 2}>
      <Block size={[w, h, d]} position={[0, h / 2, 0]} color={wall} />
      {[-1, 0, 1].map((i) => (
        <Block
          key={i}
          size={[w / 3, 0.25, d * 0.62]}
          position={[(i * w) / 3, h + 0.75, 0]}
          rotation={[0, 0, 0.5]}
          color={roof}
        />
      ))}
      <Block size={[w * 0.6, h * 0.55, 0.16]} position={[0, h * 0.5, d / 2 + 0.08]} color={SHARED.ink} />
      <Block size={[w * 0.52, h * 0.45, 0.1]} position={[0, h * 0.5, d / 2 + 0.17]} color={p.palette.accent} />
    </Shell>
  );
}

/** Arcade (experience): neon stripe and two cabinets by the door. */
export function Arcade(p: BuildingModelProps) {
  const { w, d } = body(p.plot);
  const h = 4;
  const wall = pick(p.palette.buildings, p.colourIndex);
  return (
    <Shell p={p} front={d / 2 + 1}>
      <Block size={[w, h, d]} position={[0, h / 2, 0]} color={wall} />
      <Block size={[w + 0.1, 0.35, d + 0.1]} position={[0, h - 0.6, 0]} color={p.palette.accent} emissive />
      <Door z={d / 2 + 0.06} color={SHARED.ink} width={2} />
      {[-1, 1].map((s) => (
        <group key={s} position={[s * w * 0.32, 0, d / 2 + 0.8]}>
          <Block
            size={[0.9, 1.8, 0.8]}
            position={[0, 0.9, 0]}
            color={pick(p.palette.roofs, p.colourIndex + (s > 0 ? 1 : 0))}
          />
          <Block size={[0.7, 0.5, 0.1]} position={[0, 1.35, 0.41]} color={SHARED.carGlass} />
        </group>
      ))}
    </Shell>
  );
}

/** Default model per building kind. */
export const BUILDING_MODELS: Record<BuildingKind, BuildingModel> = {
  podcast: PodcastStudio,
  interview: InterviewBooth,
  documents: Archive,
  research: ResearchLab,
  video: Cinema,
  animation: Gallery,
  experience: Arcade,
};

/** Rough height of each default model (for beacons and labels). */
export const MODEL_HEIGHT: Record<BuildingKind, number> = {
  podcast: 7.2,
  interview: 3.6,
  documents: 5.6,
  research: 7.6,
  video: 5.8,
  animation: 5,
  experience: 4.4,
};
